/**
 * THE TRIAGE SECTION'S ART SLOTS. The pixel art is generated by the owner (docs/triage-art-prompts.md)
 * and dropped into dashboard/public/triage/. Until a file exists, its slot draws a Night Glass
 * stand-in — a gradient and a line icon — so the section looks finished either way.
 *
 * Like the QA section (components/qa/art.tsx), a deliberate exception to Night Glass's "no sprites"
 * rule: the section has its own drawn art, everything around it stays Night Glass.
 *
 * TRIAGE_ART is the one list of slots: the prompt doc and the build script
 * (scripts/world/build_qa_art.py --section triage) iterate the same file names.
 */
import { useState } from 'react';

export const TRIAGE_ART = {
  hero: { file: 'hero.png', w: 1600, h: 400, alt: 'Bug triage bay' },
  'stage-intake': { file: 'stage-intake.png', w: 512, h: 512, alt: 'Intake' },
  'stage-triage': { file: 'stage-triage.png', w: 512, h: 512, alt: 'Triage' },
  'stage-code-check': { file: 'stage-code-check.png', w: 512, h: 512, alt: 'Code check' },
  'stage-reproduce': { file: 'stage-reproduce.png', w: 512, h: 512, alt: 'Reproduce' },
  'stage-fix': { file: 'stage-fix.png', w: 512, h: 512, alt: 'Fix' },
  'stage-pr': { file: 'stage-pr.png', w: 512, h: 512, alt: 'Pull request' },
  'stage-follow-up': { file: 'stage-follow-up.png', w: 512, h: 512, alt: 'Follow-up' },
  'empty-board': { file: 'empty-board.png', w: 512, h: 512, alt: 'No bugs yet' },
  paused: { file: 'paused.png', w: 512, h: 512, alt: 'Triage paused' },
} as const;

export type TriageArtName = keyof typeof TRIAGE_ART;
export const TRIAGE_ART_NAMES = Object.keys(TRIAGE_ART) as TriageArtName[];
export const triageArtSrc = (name: TriageArtName) => `/triage/${TRIAGE_ART[name].file}`;

const ICON: Record<string, string> = {
  // a bug
  hero: 'M8 9a4 4 0 0 1 8 0v5a4 4 0 0 1-8 0zM12 9v9M4 12h4M16 12h4M5 7l3 2M19 7l-3 2M5 18l3-2M19 18l-3-2',
  // an inbox tray
  'stage-intake': 'M4 13l2.5-7h11L20 13v5H4zM4 13h5l1 2h4l1-2h5',
  // a sorting funnel
  'stage-triage': 'M4 5h16l-6 7v6l-4 2v-8z',
  // a magnifier over code
  'stage-code-check': 'M10 6l-4 4 4 4M15.5 15.5L20 20M11 3a7 7 0 1 1 0 14 7 7 0 0 1 0-14z',
  // a play arrow and a cross: a failing run
  'stage-reproduce': 'M6 4l9 6-9 6zM16 15l4 4M20 15l-4 4',
  // a wrench
  'stage-fix': 'M14.5 5.5a4 4 0 0 0-5 5L4 16l4 4 5.5-5.5a4 4 0 0 0 5-5L16 12l-4-4z',
  // a pull request
  'stage-pr': 'M6 3v12M6 15a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5zM18 9v6M18 15a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5zM18 9a3 3 0 0 0-3-3h-4M13 4l-2 2 2 2',
  // a speech bubble with a tick
  'stage-follow-up': 'M4 5h16v11H9l-5 4zM9 11l2 2 4-4',
  // an empty tray
  'empty-board': 'M4 13l2.5-7h11L20 13v5H4zM4 13h16',
  // pause
  paused: 'M12 3a9 9 0 1 1 0 18 9 9 0 0 1 0-18zM10 9v6M14 9v6',
};

/**
 * One art slot. Shows the drawn image; if it is missing (or fails to load) shows the stand-in.
 * `className` sizes the slot; the image keeps its own aspect ratio inside it.
 */
export function TriageArt({ name, className = '' }: { name: TriageArtName; className?: string }) {
  const [missing, setMissing] = useState(false);
  const art = TRIAGE_ART[name];
  return (
    <div
      data-triage-art={name}
      data-triage-art-fallback={missing || undefined}
      className={`relative overflow-hidden rounded-[18px] border border-white/[0.08] ${className}`}
      style={{ aspectRatio: `${art.w} / ${art.h}` }}
    >
      {missing ? (
        <div
          role="img"
          aria-label={art.alt}
          className="absolute inset-0 flex items-center justify-center text-neon-200/80 bg-[radial-gradient(ellipse_at_30%_20%,rgba(90,174,255,0.28),transparent_60%),radial-gradient(ellipse_at_80%_90%,rgba(242,114,54,0.16),transparent_55%)] bg-gl-surface"
        >
          <svg viewBox="0 0 24 24" className="w-1/3 h-1/3 max-w-[96px]" fill="none" stroke="currentColor" strokeWidth={1.6} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d={ICON[name]} />
          </svg>
        </div>
      ) : (
        <img
          src={triageArtSrc(name)}
          alt={art.alt}
          draggable={false}
          onError={() => setMissing(true)}
          className="absolute inset-0 w-full h-full object-cover [image-rendering:pixelated]"
        />
      )}
    </div>
  );
}
